import type { ReactNode } from 'react'
import './index.less'

interface SolutionSectionProps {
  image: string
  imageAlt?: string
  reverse?: boolean
  tone?: 'default' | 'gray' | 'rounded'
  spacing?: 'normal' | 'loose'
  children: ReactNode
  className?: string
}

const SolutionSection = ({
  image,
  imageAlt = '',
  reverse = false,
  tone = 'default',
  spacing = 'normal',
  children,
  className = '',
}: SolutionSectionProps) => {
  const classNames = [
    'solution-section',
    reverse ? 'solution-section--reverse' : '',
    `solution-section--${tone}`,
    `solution-section--${spacing}`,
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <section className={classNames}>
      <div className="solution-section__image">
        <img src={image} alt={imageAlt} />
      </div>
      <div className="solution-section__content">{children}</div>
    </section>
  )
}

export default SolutionSection
