import type { ReactNode, ElementType } from 'react'
import './index.less'

interface CTextProps {
  children: ReactNode
  variant?: 'body' | 'desc'
  as?: 'p' | 'span' | 'div'
  align?: 'left' | 'center'
  className?: string
}

const CText = ({
  children,
  variant = 'desc',
  as = 'p',
  align,
  className = '',
}: CTextProps) => {
  const Tag = as as ElementType

  const classNames = [
    'c-text',
    `c-text--${variant}`,
    align ? `c-text--${align}` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <Tag className={classNames}>{children}</Tag>
}

export default CText
