import './index.less'

interface CMediaImageProps {
  src: string
  alt?: string
  frame?: 'full' | 'card'
  className?: string
}

const CMediaImage = ({
  src,
  alt = '',
  frame = 'full',
  className = '',
}: CMediaImageProps) => {
  const classNames = [
    'c-media-image',
    `c-media-image--${frame}`,
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <img className={classNames} src={src} alt={alt} />
}

export default CMediaImage
